194	// clusterHostLabelRe matches one DNS label: alphanumeric, internal hyphens
195	// allowed, no leading/trailing hyphen.
196	var clusterHostLabelRe = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$`)
197	
198	// validateClusterHost rejects a cluster host that is anything other than a
199	// bare DNS name or IP with an optional :port. The host is concatenated as
200	// "https://"+host into the clone URL and the STS audience
201	// (entireclient/repocreds), so a value carrying URL metacharacters can redirect
202	// the request — and the repo-scoped basic-auth token it carries — somewhere
203	// other than the intended cluster. Classic case:
204	// `aws-us-east-2.entire.io@evil.com`, which Go's URL parser reads as
205	// host=evil.com with the real cluster demoted to userinfo, leaking the token
206	// to evil.com. We parse the host the same way the rest of the code does and
207	// require it to round-trip to a bare host with no userinfo, path, query, or
208	// fragment, then confirm the hostname is a valid IP or DNS name. This is
209	// cheap client-side defense-in-depth and doesn't depend on the server's STS
210	// invalid_target canonicalization catching the trick.
211	func validateClusterHost(host string) error {
212		if strings.TrimSpace(host) == "" {
213			return errors.New("cluster host is empty")
214		}
215		u, err := url.Parse("https://" + host)
216		if err != nil {
217			return fmt.Errorf("%q is not a valid host", host)
218		}
219		if u.User != nil || u.Path != "" || u.RawQuery != "" || u.Fragment != "" || u.Host != host {
220			return fmt.Errorf("%q must be a bare host[:port] (no scheme, userinfo, path, query, or fragment)", host)
221		}
222		hostname := u.Hostname()
223		if net.ParseIP(hostname) != nil {
224			return nil
225		}
226		for _, label := range strings.Split(hostname, ".") {
227			if !clusterHostLabelRe.MatchString(label) {
228				return fmt.Errorf("%q is not a valid DNS name or IP", host)
229			}
230		}
231		return nil
232	}
